def find_path(graph, start, goal):
    # Implementing a stack-based DFS approach
    stack = [(start, [start])]  # Initialize the stack with the start node and a path containing the start node
    visited = set()

    while stack:
        current_node, path = stack.pop()
        if current_node == goal:
            return path  # Found a path to the goal node
        if current_node not in visited:
            visited.add(current_node)
            for neighbor in graph.get(current_node, []):
                stack.append((neighbor, path + [neighbor]))  # Push the neighbor and the updated path onto the stack

    return None  # Goal node is unreachable
