```python
def find_path(graph, start, goal):
    if start == goal:
        return [start]  # Return the start node as the path

    visited = set()  # Set to keep track of visited nodes
    stack = [(start, [start])]  # Initialize stack with start node and path

    while stack:
        (current_node, path) = stack.pop()
        if current_node not in visited:
            visited.add(current_node)
            if current_node == goal:
                return path  # Return the path if the goal node is reached
            neighbours = graph.get(current_node, [])
            for neighbour in neighbours:
                if neighbour not in visited:
                    stack.append((neighbour, path + [neighbour]))  # Add neighbour and updated path to stack

    return None  # Return None if goal is unreachable

