def find_path(graph, start, goal):
    if start == goal:
        return [start]

    visited = set()
    queue = deque([(start, [start])])  # (node, path)

    while queue:
        (node, path) = queue.popleft()
        visited.add(node)

        for next_node in graph[node]:
            if next_node not in visited:
                if next_node == goal:
                    return path + [next_node]
                else:
                    queue.append((next_node, path + [next_node]))

    return None
