def find_path(graph, start, goal):
    # Helper function to perform DFS and keep track of visited nodes
    def dfs(start, goal, path):
        visited = set()
        stack = [(start, [start])]
        while stack:
            (node, path) = stack.pop()
            visited.add(node)
            if node == goal:
                return path
            for neighbour in graph.get(node, []):
                if neighbour not in visited:
                    stack.append((neighbour, path + [neighbour]))
        return None

    # Perform DFS from start node
    return dfs(start, goal, [start])

